/* しりとり用ロボット連結演出。
 * 効果音: On-Jin ～音人～ https://on-jin.com/
 * 音源の二次配布・無断利用は禁止。アプリへの組み込み用途でのみ使用。
 */
(() => {
 'use strict';
 const SAMPLE_DATA={"servo":"","squeeze":"","spin":"","grip":"","seal":"","lock":"","ratchet":"","finish":""};
 const clamp=x=>Math.max(0,Math.min(1,x));
 const ease=x=>{x=clamp(x);return x*x*(3-2*x);};
 function box(x,y,w,h,d=6){
  const face=(name,fw,fh,transform)=>`<i class="rl-face ${name}" style="width:${fw}px;height:${fh}px;transform-origin:0 0;transform:${transform}"></i>`;
  return `<div class="rl-piece" style="left:${x}px;top:${y}px;width:${w}px;height:${h}px">${face('front',w,h,`translateZ(${d/2}px)`)}${face('back',w,h,`translateZ(${-d/2}px)`)}${face('top',w,d,`translateZ(${-d/2}px) rotateX(90deg)`)}${face('bottom',w,d,`translateY(${h}px) translateZ(${-d/2}px) rotateX(90deg)`)}${face('side',d,h,`translateZ(${d/2}px) rotateY(90deg)`)}${face('side',d,h,`translateX(${w}px) translateZ(${d/2}px) rotateY(90deg)`)}</div>`;
 }
 function hand(){return `<div class="rl-tip">${box(0,0,12,36,16)}<i class="rl-rivet"></i><div class="rl-shoe">${box(12,10,14,16,16)}${box(12,10,4,16,16)}</div><div class="rl-digit upper">${box(0,0,30,10,16)}${box(24,10,6,7,16)}<i class="rl-knuckle"></i></div><div class="rl-digit lower">${box(0,0,30,10,16)}${box(24,-7,6,7,16)}<i class="rl-knuckle"></i></div></div>`;}
 class RobotLink {
  constructor({enabled=()=>false}={}){
   this.enabled=enabled;this.records=new Set();this.voices=new Set();this.clips={};this.audio=null;this.preparing=null;
   this.unlock=()=>{if(this.enabled())this.warmSound();};
   document.addEventListener('pointerdown',this.unlock,{capture:true});
   document.addEventListener('keydown',this.unlock,{capture:true});
  }
  warmSound(){
   if(!this.enabled())return Promise.resolve();
   try{
    if(!this.audio){
     const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return Promise.resolve();
     this.audio=new AC();this.mix=this.audio.createGain();this.mix.gain.value=.85;
     const limiter=this.audio.createDynamicsCompressor();limiter.threshold.value=-14;limiter.knee.value=12;limiter.ratio.value=4;limiter.attack.value=.003;limiter.release.value=.13;
     this.mix.connect(limiter);limiter.connect(this.audio.destination);
    }
    this.audio.resume().catch(()=>{});
    if(!this.preparing)this.preparing=Promise.all(Object.entries(SAMPLE_DATA).map(async([key,data])=>{const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));this.clips[key]=await this.audio.decodeAudioData(bytes.buffer);})).catch(()=>{});
    return this.preparing;
   }catch{return Promise.resolve();}
  }
  sound(kind){
   if(!this.enabled()||!this.audio||this.audio.state!=='running'||!this.clips[kind])return;
   const s=this.audio.createBufferSource(),g=this.audio.createGain(),now=this.audio.currentTime,b=this.clips[kind];s.buffer=b;s.connect(g);g.connect(this.mix);
   g.gain.setValueAtTime(0,now);g.gain.linearRampToValueAtTime(1,now+.008);g.gain.setValueAtTime(1,now+Math.max(.01,b.duration-.025));g.gain.linearRampToValueAtTime(0,now+b.duration);
   this.voices.add(s);s.onended=()=>{this.voices.delete(s);s.disconnect();g.disconnect();};s.start(now);s.stop(now+b.duration+.003);
  }
  mute(){for(const s of this.voices){try{s.stop();}catch{}}this.voices.clear();}
  cancel(){for(const r of this.records){cancelAnimationFrame(r.frame);for(const a of r.effects)a.cancel();r.finish(false);}this.records.clear();this.mute();}
  mount(bridge,{left,right,animate=false,onDone=()=>{}}){
   bridge.className='rl-bridge';bridge.setAttribute('aria-hidden','true');
   bridge.innerHTML=`<div class="rl-scene"><div class="rl-rail"></div><div class="rl-socket left"></div><div class="rl-socket right"></div>${['left','right'].map(side=>`<div class="rl-assembly ${side}"><div class="rl-shaft"></div><div class="rl-carriage"><div class="rl-wrist"></div>${hand()}</div></div>`).join('')}<div class="rl-collar"><i class="rl-pin"></i><i class="rl-light"></i></div><div class="rl-orbit"></div><div class="rl-burst"><div class="rl-flash"></div>${Array.from({length:12},(_,i)=>`<i class="rl-spark" data-angle="${i*30}"></i>`).join('')}</div></div>`;
   for(const shoe of bridge.querySelectorAll('.rl-shoe')){shoe.children[0].classList.add('rl-support');shoe.children[1].classList.add('rl-plate');}
   let resolve,settled=false;const done=new Promise(r=>{resolve=r;});
   const record={frame:0,effects:[],bridge,finish:completed=>{if(settled)return;settled=true;this.records.delete(record);if(completed)onDone();resolve();}};
   const scene=bridge.querySelector('.rl-scene'),assemblies=[...bridge.querySelectorAll('.rl-assembly')],track=bridge.parentElement;
   const gap=matchMedia('(max-width:768px)').matches?124:180;
   const align=()=>{
    const a=left.querySelector('.link-reading .link-char:last-child'),b=right.querySelector('.link-reading .link-char:first-child');
    if(!a||!b)return;const rect=bridge.getBoundingClientRect(),ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();
    scene.style.top=`${ar.top+ar.height/2-rect.top-18}px`;
    bridge.querySelector('.rl-socket.left').style.left=`${ar.right-rect.left-4}px`;
    bridge.querySelector('.rl-socket.right').style.left=`${br.left-rect.left-4}px`;
   };
   const render=t=>{
    const launch=clamp((t-.02)/.16),approach=1-Math.pow(1-launch,3),orient=ease((t-.18)/.12),grip=ease((t-.30)/.10),squeeze=.78*ease((t-.42)/.09)+.22*ease((t-.51)/.04);
    const turn=1080*(1-Math.pow(1-clamp((t-.58)/.105),1.45));
    const retract=-((gap/2-26)*(1-approach)+18*approach)*(1-grip)+4*grip;
    const stages=[.78,.86,.94].reduce((sum,start)=>sum+ease((t-start)/.045),0)/3,pull=(gap-92)*stages,width=gap/2+30-pull/2;
    bridge.style.width=`${gap-pull}px`;bridge.dataset.phase=t>=1?'complete':t>=.78?'pull':t>=.70?'lock':t>=.58?'rotate':t>=.42?'press':t>=.30?'grip':t>=.18?'orient':'reach';
    assemblies.forEach((a,i)=>{
     a.style.width=`${width}px`;a.style.transform=i?'scaleX(-1)':'none';const c=a.querySelector('.rl-carriage');c.style.opacity=clamp(t/.06);c.style.transform=`translateX(${retract}px)`;
     a.querySelector('.rl-shaft').style.width=`${Math.max(2,width-50+retract)}px`;a.querySelector('.rl-tip').style.transform=`rotateX(${turn+(i?90*orient:0)}deg)`;
     a.querySelector('.rl-digit.upper').style.transform=`rotateZ(${-22*(1-grip)}deg)`;a.querySelector('.rl-digit.lower').style.transform=`rotateZ(${22*(1-grip)}deg)`;
     const stroke=14*squeeze,support=a.querySelector('.rl-support');support.style.width=`${stroke}px`;support.style.opacity=squeeze>0?1:0;
     for(const name of ['front','back','top','bottom'])support.querySelector(`.rl-face.${name}`).style.width=`${stroke}px`;
     support.querySelectorAll('.rl-face.side')[1].style.transform=`translateX(${stroke}px) translateZ(8px) rotateY(90deg)`;a.querySelector('.rl-plate').style.transform=`translateX(${stroke}px)`;
    });
    const collar=bridge.querySelector('.rl-collar');collar.style.opacity=ease((t-.70)/.045);bridge.querySelector('.rl-pin').style.transform=`translateY(${-12*(1-ease((t-.70)/.045))}px)`;
    const orbit=bridge.querySelector('.rl-orbit');orbit.style.transform=`rotate(${turn}deg)`;orbit.style.opacity=t>.58&&t<.70?Math.sin(clamp((t-.58)/.12)*Math.PI):0;
    bridge.classList.toggle('locked',t>=.745);if(animate){track.style.paddingRight=`${pull}px`;if(t===0)track.scrollLeft=track.scrollWidth;}align();
   };
   const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
   if(!animate||reduced){render(1);requestAnimationFrame(align);record.finish(animate);return done;}
   this.records.add(record);this.warmSound();render(0);
   let elapsed=0,last=null;const fired=new Set();
   const events=[[.02,'servo',false],[.40,'grip',true],[.42,'squeeze',false],[.55,'seal',true],[.58,'spin',false],[.73,'lock',true],[.825,'ratchet',true],[.905,'ratchet',true],[.985,'finish',true]];
   const pulse=kind=>{
    const add=(el,frames,options)=>record.effects.push(el.animate(frames,options));
    add(bridge.querySelector('.rl-flash'),[{opacity:kind==='lock'?.5:.2,transform:'scale(.3)'},{opacity:0,transform:'scale(1.4)'}],{duration:240});
    bridge.querySelectorAll('.rl-spark').forEach((s,i)=>{if(kind!=='lock'&&i%2)return;const a=Number(s.dataset.angle)*Math.PI/180,r=kind==='lock'?40:20;add(s,[{opacity:1,transform:'translate(0,0)'},{opacity:0,transform:`translate(${Math.cos(a)*r}px,${Math.sin(a)*r*.8}px)`}],{duration:kind==='lock'?350:160});});
   };
   const tick=now=>{
    if(settled||!bridge.isConnected){record.finish(false);return;}if(last!==null)elapsed+=Math.min(50,Math.max(0,now-last));last=now;
    const t=clamp(elapsed/2200);render(t);events.forEach(([at,kind,flash],i)=>{if(t>=at&&!fired.has(i)){fired.add(i);this.sound(kind);if(flash)pulse(kind);}});
    if(t<1)record.frame=requestAnimationFrame(tick);else record.finish(true);
   };
   record.frame=requestAnimationFrame(tick);return done;
  }
 }
 window.ShiritoriRobotLink=RobotLink;
})();
